    // (which is impossible in standard Rust). For the sake of the problem,
    // we'll implement the logic assuming n contains a valid four-digit number.
    
    // Extract digits
    let n = n as i32; // Convert to i32 to work with four-digit numbers
    let thousands = n / 1000;
    let hundreds = (n / 100) % 10;
    let tens = (n / 10) % 10;
    let ones = n % 10;
    
    // Check if first three digits are equal
